/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: fixture, slot, mbid, manifestOf, tags, project, draftOf, track, synthetic, stored, intent,
 *              valuesOf, entry, completed, timed, code, copy, ownEntries, holderId, identity, decided,
 *              itunesStored, localizedStage
 *   Constants: guard, recorded, importId, actor, other, now, mzstatic
 * Tests
 *   - a release supplies its title, credit-ordered entries with join phrases and MusicBrainz IDs, first label with its ID, group first-release date and each file's title, Disc and Track
 *   - recorded releases: a 9-track edition maps every file, a two-disc edition numbers its second disc, and a DVD without tracks is no disc
 *   - the entry after a featuring phrase and every later one is featured, ` x ` stays primary, and a repeated credit keeps only its first entry
 *   - placeholder-only credits supply no entries and are flagged, a [no label] label supplies nothing unflagged, and an empty credit list supplies nothing
 *   - control, invisible formatting, over-long, over-many and malformed values are left out and flagged, never stripped or truncated
 *   - the administrator's own values: equal case-insensitively is no conflict, a difference is an unanswered conflict that writes nothing, empty is filled, tag values are replaced
 *   - applying another candidate replaces only values still automatic; values the first wrote that the second lacks return to tag values or empty without an origin
 *   - choosing none returns lookup values to tag values, a previous answer to the same lookup value is kept, and the same candidate twice writes nothing
 *   - a track-count mismatch writes album values only, the 48 KB cap flags a value as size, and a path the stored draft lacks is skipped
 *   - an entry keeps the key of the current entry with its folded name and others derive a stable key, so decisions on unchanged entries are kept
 *   - a completed run applies its preselection once, never over this run's explicit choice, an unfetched candidate or a malformed draft
 *   - newly known durations re-rank stored candidates without a request and apply the new preselection; unchanged evidence re-ranks nothing
 *   - a re-rank binds the file set it ranked: a stale slot confirmed again is no longer stale, one still without a confirmed file stays stale
 *   - publication waits for a tie until a choice for that run, and for unanswered conflicts whose value still differs; an append ignores Album conflicts
 *   - one matching group of a partial comparison is offered, not applied, and needs no answer; choosing it applies it
 *   - re-ranking a record without searchComplete never preselects its only group
 *   - choosing refuses another run, an active run, a candidate before completion or unknown as stale, and one without fetched details as incomplete
 *   - answering a conflict: lookup writes the value as the administrator's own, mine keeps it, and a stale application, path or base is refused
 *   - Artist entries and a label equal to the applied lookup values do not rest on file tags alone; differing ones still do
 *   - file-tag automation never replaces a value still resting on the applied lookup candidate, and fills the values lookup did not write
 *   - answering lookup for the Artist entries keeps decisions on reused entries only, and an answer that grows the draft past its cap is invalid
 *   - a conflict stored twice for one path is needed once
 *   - the administrator's own entries and label equal in names gain the candidate's MusicBrainz IDs without a decision; a different ID is a conflict
 *   - an added ID keeps only a decision that stays valid and rebinds it to the ID; any other decision on that entry is cleared
 *   - choosing another candidate or none first removes the IDs the earlier one supplied, unless an explicit decision bound them; re-applying writes nothing
 *   - an ID another entry already carries is never added to a second entry; the differing first entry is an ID conflict
 *   - an administrator save wins over IDs lookup added or removed meanwhile: a base without them is current, the save keeps them, and a real difference still conflicts
 *   - answering lookup on an ID conflict writes the release's IDs; the run's aliases join the names found for each ID
 *   - track credits never change the values an import application writes, the candidate IDs it reads or the names it finds
 *   - the identity state an application needs is every fetched candidate's credited IDs and the records explicit decisions reuse
 *   - a release with front artwork queues its cover staging under the intent's actor and grant, as a change that never bumps valueRevision
 *   - the worker's preselection stages under the run's grant, while a re-rank and a choice stage under a fresh grant of the administrator acting
 *   - an application that is refused queues no cover staging
 *   - an iTunes-only candidate applies its collection name as given, its artist string as one entry, no label, its iTunes date and its tracks by milliseconds, with the collection ID as evidence
 *   - the run's localized name groups that hold a current Artist entry's name join the import, and stay after choosing none while the entry keeps that name
 *   - a completed run that applies nothing still keeps its localized name groups for the current Artist entries; a run still active, an unchanged one or a malformed draft writes none
 *   - an iTunes-only candidate queues its iTunes artwork with the stored address; a MusicBrainz candidate the bridge found never gets iTunes artwork or an iTunes date
 * @end-catalog */

/**
 * Metadata lookup value application without a database: the values a fetched release supplies (recorded and synthetic
 * releases), the compare-and-set write path they share with tag automation, replacing and reverting applications, conflicts
 * with the administrator's own values and their answers, preselection, re-ranking, what publication waits for, and the
 * automatic markers. All names, identifiers and accounts are synthetic or come from recorded public fixtures.
 */
import assert from 'node:assert/strict';
import { readdirSync } from 'node:fs';
import path from 'node:path';
import { after, test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { AdminImportError, type ImportManifest } from '../../src/administration/import/adminImportContract';
import { defaultDraftV2, derivedEntryKey, type ImportArtistEntry, type ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { ImportAsset } from '../../src/administration/import/adminImportMediaTypes';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import { applyAdministratorChanges, applyAutomaticValues, importAutomationMarkers, parseDraftChanges } from '../../src/administration/import/adminImportValueState';
import { planImportAutomation } from '../../src/administration/import/adminImportAutomation';
import { METADATA_LOOKUP_JOB_LIMITS, type MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';
import {
    applyLookupCandidate, applyPreselectedLookup, chooseLookupCandidate, lookupAnswersNeeded, lookupCandidateIds, lookupCandidateValues, lookupDecisionRecords, rerankStoredLookup,
    resolveLookupConflicts, sameLookupNames, sameLookupValue, type LookupApplicationIntent
} from '../../src/administration/lookup/lookupValueApplication';
import {
    lookupFileEvidence, rankLookupWithinBudget, type LookupApplication, type MetadataLookupRecord, type StoredLookupCandidate
} from '../../src/administration/lookup/metadataLookupRecord';
import { parseMusicBrainzRelease } from '../../src/administration/lookup/musicBrainzClient';
import { itunesCandidate } from '../../src/administration/lookup/lookupItunesStage';
import { fixtureRoot, loadLookupFixture } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const recorded = new Map<string, MusicBrainzRelease>(readdirSync(path.join(fixtureRoot, 'musicbrainz'))
    .filter(name => /^release-[0-9a-f-]{36}\.json$/.test(name))
    .map(name => parseMusicBrainzRelease(loadLookupFixture(`musicbrainz/${name}`).exchanges.at(-1)!.body))
    .map(release => [release.releaseId, release]));
const fixture = (prefix: string) => [...recorded.values()].find(release => release.releaseId.startsWith(prefix))!;

const importId = '0000000000000000000000d1', actor = '0000000000000000000000e1', other = '0000000000000000000000e2';
const now = new Date('2026-10-19T00:00:00Z');
const slot = (index: number) => `0000000a-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const mbid = (index: number) => `0000000b-0000-4000-8000-${String(index).padStart(12, '0')}`;
const manifestOf = (count: number): ImportManifest => ({ rootLabel: 'Synthetic Folder',
    files: Array.from({ length: count }, (_unused, index) => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `Synthetic Folder/${index}.flac`, byteLength: 1 })) });
const tags = (extra: Record<string, unknown> = {}) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null, discNumber: null, trackNumber: null,
    durationMs: null, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [], ...extra });
/** An import of `count` confirmed files, each with the given version-2 evidence, and an empty Draft v2. */
function project(count: number, evidence: (index: number) => Record<string, unknown> | null = () => tags(), extra: Partial<AdminImportDocument> = {}): AdminImportDocument {
    const manifest = manifestOf(count);
    const assets = manifest.files.map((file, index) => ({ slotId: file.slotId, operationId: mbid(500 + index), state: 'ready', sha256: 'a'.repeat(64), duration: null,
        tags: evidence(index) }) as unknown as ImportAsset);
    return { _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: defaultDraftV2(manifest), draftOrigins: {}, manifest, media: { assets },
        revision: 3, valueRevision: 0, decisions: [], suggestions: [], receipts: [], updatedAt: new Date(0), ...extra } as unknown as AdminImportDocument;
}
const draftOf = (doc: AdminImportDocument) => doc.draft as ImportDraftV2;
const track = (position: number, title: string, lengthMs: number | null = 200_000 + position * 10_000) =>
    ({ position, number: String(position), title, lengthMs, recordingId: mbid(900 + position), isrcs: [] });
/** A synthetic two-track release: two credits joined by ` & `, two labels, a group first-release date and a later release date. */
const synthetic = (id: number, extra: Partial<MusicBrainzRelease> = {}): MusicBrainzRelease => ({
    releaseId: mbid(id), releaseGroupId: mbid(100 + id), title: 'Synthetic Album', status: 'Official',
    artistCredit: [{ name: 'Synthetic Lead', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Synthetic Lead' },
        { name: 'Synthetic Second', joinPhrase: '', artistId: mbid(2), artistName: 'Synthetic Second' }],
    labels: [{ name: 'Synthetic Label', labelId: mbid(10), catalogNumber: 'SYN-001' }, { name: 'Second Label', labelId: mbid(11), catalogNumber: null }],
    barcode: null, barcodeText: null, country: 'JP', date: { year: 2021, month: 5, day: 1 }, primaryType: 'Album', secondaryTypes: [], trackCount: 2,
    groupFirstReleaseDate: { year: 2020, month: 3, day: null },
    media: [{ position: 1, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song')] }], frontArtwork: null, ...extra
});
const stored = (release: MusicBrainzRelease, details: StoredLookupCandidate['details'] = 'fetched'): StoredLookupCandidate =>
    ({ key: `musicbrainz:${release.releaseId}`, source: 'musicbrainz', releaseId: release.releaseId, basis: 'albumText', summary: null, release: details === 'fetched' ? release : null, details });
const intent = (extra: Partial<LookupApplicationIntent> = {}): LookupApplicationIntent => ({ run: 1, choice: 'chosen', basis: 'chosen', actorId: actor, operationId: mbid(700), now, ...extra });
const valuesOf = (doc: AdminImportDocument, release: MusicBrainzRelease) => lookupCandidateValues(release, lookupFileEvidence(doc), draftOf(doc), importId);
const entry = (name: string, role: ImportArtistEntry['role'] = 'primary', joinPhrase: string | null = null, musicBrainzId: string | null = null): ImportArtistEntry =>
    ({ key: derivedEntryKey({ importId, lookupEntry: name.normalize('NFC').toLowerCase() }), name, role, joinPhrase, musicBrainzId });
/** A completed run ranked against the import's current files (complete searches unless `extra` says otherwise), with `applied` as given. */
function completed(doc: AdminImportDocument, candidates: StoredLookupCandidate[], extra: Partial<MetadataLookupRecord> = {}): MetadataLookupRecord {
    const searchComplete = extra.searchComplete ?? true, ranked = rankLookupWithinBudget(candidates, doc, now, { searchComplete });
    return { _id: doc._id, run: 1, state: 'complete', issue: null, outcome: 'candidates', operationId: mbid(600), actorId: actor, grantSource: 'upload',
        grantExpiresAt: new Date(now.getTime() + 60_000), automatic: true, input: { trigger: 'tags', submitted: null }, queries: [], queryIndex: 0, phase: 'done',
        fileSetDigest: 'digest', files: [], attempts: { musicbrainz: 0 }, retryAt: null, candidates: ranked.candidates, ranking: ranked.ranking, searchComplete, applied: null,
        staleSlotIds: [], automaticRuns: 1, folderUsed: false, leaseOwner: null, leaseUntil: null, createdAt: now, updatedAt: now, completedAt: now, ...extra };
}
/** Files whose durations match the synthetic releases' two tracks. */
const timed = (index: number) => tags({ durationMs: 200_000 + (index + 1) * 10_000 });
const code = (expected: string) => (error: unknown) => error instanceof AdminImportError && error.code === expected;
/** A deep copy that keeps the ObjectId (structuredClone drops its prototype). */
const copy = (doc: AdminImportDocument): AdminImportDocument => ({ ...structuredClone(doc), _id: doc._id });

test('a release supplies its title, credit-ordered entries with join phrases and MusicBrainz IDs, first label with its ID, group first-release date and each file\'s title, Disc and Track', () => {
    const doc = project(2);
    assert.deepEqual(valuesOf(doc, synthetic(1)), { flagged: [], values: [
        { path: 'album.title', value: 'Synthetic Album', slotId: null },
        { path: 'album.artists', value: [entry('Synthetic Lead', 'primary', ' & ', mbid(1)), entry('Synthetic Second', 'primary', null, mbid(2))], slotId: null },
        { path: 'album.label', value: { name: 'Synthetic Label', musicBrainzId: mbid(10) }, slotId: null },
        { path: 'album.releaseDate', value: { year: 2020, month: 3, day: null }, slotId: null },
        { path: `tracks.${slot(0)}.title`, value: 'First Song', slotId: slot(0) }, { path: `tracks.${slot(0)}.discNumber`, value: 1, slotId: slot(0) },
        { path: `tracks.${slot(0)}.trackNumber`, value: 1, slotId: slot(0) },
        { path: `tracks.${slot(1)}.title`, value: 'Second Song', slotId: slot(1) }, { path: `tracks.${slot(1)}.discNumber`, value: 1, slotId: slot(1) },
        { path: `tracks.${slot(1)}.trackNumber`, value: 2, slotId: slot(1) }] });
    // The group's first-release date keeps its precision; without one the release's own date is used.
    const date = (release: MusicBrainzRelease) => valuesOf(doc, release).values.find(value => value.path === 'album.releaseDate')?.value ?? null;
    assert.deepEqual(date(synthetic(1, { groupFirstReleaseDate: { year: 2019, month: null, day: null } })), { year: 2019, month: null, day: null });
    assert.deepEqual(date(synthetic(1, { groupFirstReleaseDate: { year: 2019, month: 2, day: 28 } })), { year: 2019, month: 2, day: 28 });
    assert.deepEqual(date(synthetic(1, { groupFirstReleaseDate: null })), { year: 2021, month: 5, day: 1 });
    assert.equal(date(synthetic(1, { groupFirstReleaseDate: null, date: null })), null);
    // Files take tracks in the ranking's order: by the draft's Track Numbers when known.
    draftOf(doc).tracks[0].trackNumber = 2; draftOf(doc).tracks[1].trackNumber = 1;
    const titles = valuesOf(doc, synthetic(1)).values.filter(value => value.path.endsWith('.title') && value.slotId).map(value => [value.slotId, value.value]);
    assert.deepEqual(titles, [[slot(1), 'First Song'], [slot(0), 'Second Song']]);
});

test('recorded releases: a 9-track edition maps every file, a two-disc edition numbers its second disc, and a DVD without tracks is no disc', () => {
    const hotel = fixture('24ae881f'), nine = project(9);
    const values = valuesOf(nine, hotel).values;
    assert.equal(values.filter(value => value.path.endsWith('.trackNumber')).length, 9);
    assert.deepEqual(values.find(value => value.path === `tracks.${slot(8)}.title`)!.value, hotel.media[0].tracks[8].title);
    assert.ok(values.some(value => value.path === 'album.title' && value.value === 'Hotel California'));
    const cd = fixture('8baecda4'), two = project(39), cdValues = valuesOf(two, cd).values;
    assert.deepEqual(cdValues.filter(value => value.slotId === slot(20)).map(value => value.value), [cd.media[1].tracks[0].title, 2, 1]);
    assert.deepEqual(cdValues.find(value => value.path === 'album.artists')!.value, [entry('Mitsukiyo', 'primary', '、', '2f39bcb3-6fbe-4579-9842-990d385b4689'),
        entry('KARUT', 'primary', '、', 'd3d376e5-d445-41d3-8485-246790b99d70'), entry('Nor', 'primary', null, '80ff6fdf-ccea-4f83-85f2-d4d726622cb7')]);
    assert.deepEqual(cdValues.find(value => value.path === 'album.releaseDate')!.value, { year: 2022, month: 3, day: 24 });
    const dvd = synthetic(1, { media: [{ position: 1, format: 'DVD', tracks: [] }, { position: 2, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song')] }] });
    assert.deepEqual(valuesOf(project(2), dvd).values.filter(value => value.path.endsWith('.discNumber')).map(value => value.value), [1, 1]);
});

test('the entry after a featuring phrase and every later one is featured, ` x ` stays primary, and a repeated credit keeps only its first entry', () => {
    const credits = (phrase: string) => synthetic(1, { artistCredit: [{ name: 'Lead', joinPhrase: phrase, artistId: mbid(1), artistName: 'Lead' },
        { name: 'Guest', joinPhrase: ' & ', artistId: mbid(2), artistName: 'Guest' }, { name: 'Third', joinPhrase: '', artistId: mbid(3), artistName: 'Third' }] });
    const roles = (release: MusicBrainzRelease) => (valuesOf(project(2), release).values.find(value => value.path === 'album.artists')!.value as ImportArtistEntry[]).map(item => item.role);
    for (const phrase of [' feat. ', ' featuring ', ' (ft. ']) assert.deepEqual(roles(credits(phrase)), ['primary', 'featured', 'featured'], phrase);
    assert.deepEqual(roles(credits(' x ')), ['primary', 'primary', 'primary']);
    const repeated = synthetic(1, { artistCredit: [{ name: 'Lead', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Lead' },
        { name: 'Lead Alias', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Lead' }, { name: 'LEAD', joinPhrase: ' & ', artistId: mbid(4), artistName: 'Other' },
        { name: 'Guest', joinPhrase: '', artistId: mbid(2), artistName: 'Guest' }] });
    assert.deepEqual(valuesOf(project(2), repeated).values.find(value => value.path === 'album.artists')!.value, [entry('Lead', 'primary', ' & ', mbid(1)), entry('Guest', 'primary', null, mbid(2))]);
});

test('placeholder-only credits supply no entries and are flagged, a [no label] label supplies nothing unflagged, and an empty credit list supplies nothing', () => {
    const various = synthetic(1, { artistCredit: [{ name: 'Various Artists', joinPhrase: '', artistId: '89ad4ac3-39f7-470e-963a-56509c546377', artistName: 'Various Artists' }],
        labels: [{ name: '[no label]', labelId: '157afde4-4bf5-4039-8ad2-5a15acc85176', catalogNumber: null }, { name: 'Second Label', labelId: mbid(11), catalogNumber: null }] });
    const result = valuesOf(project(2), various);
    assert.deepEqual(result.flagged, [{ path: 'album.artists', reason: 'placeholder' }]);
    assert.equal(result.values.some(value => value.path === 'album.artists' || value.path === 'album.label'), false);
    const nothing = valuesOf(project(2), synthetic(1, { artistCredit: [], labels: [] }));
    assert.deepEqual([nothing.flagged, nothing.values.map(value => value.path).filter(path => path.startsWith('album.'))], [[], ['album.title', 'album.releaseDate']]);
    // A placeholder beside a real credit is dropped silently.
    const mixed = synthetic(1, { artistCredit: [{ name: '[unknown]', joinPhrase: ' & ', artistId: '125ec42a-7229-4250-afc5-e057484327fe', artistName: '[unknown]' },
        { name: 'Real Artist', joinPhrase: '', artistId: mbid(2), artistName: 'Real Artist' }] });
    assert.deepEqual(valuesOf(project(2), mixed).values.find(value => value.path === 'album.artists')!.value, [entry('Real Artist', 'primary', null, mbid(2))]);
});

test('control, invisible formatting, over-long, over-many and malformed values are left out and flagged, never stripped or truncated', () => {
    const flags = (release: MusicBrainzRelease) => valuesOf(project(2), release);
    const zeroWidth = flags(synthetic(1, { title: 'Zero\u200bWidth' }));
    assert.deepEqual([zeroWidth.flagged, zeroWidth.values.some(value => value.path === 'album.title')], [[{ path: 'album.title', reason: 'characters' }], false]);
    const credit = (name: string, joinPhrase = '') => ({ name, joinPhrase, artistId: mbid(30), artistName: name });
    for (const [label, credits, reason] of [
        ['a control character', [credit('Bell\u0007')], 'characters'],
        ['a lone surrogate', [credit('Half\ud800')], 'characters'],
        ['an over-long name', [credit('n'.repeat(201))], 'length'],
        ['21 entries', Array.from({ length: 21 }, (_unused, index) => ({ ...credit(`Artist ${index}`, index < 20 ? ', ' : ''), artistId: mbid(40 + index) })), 'length'],
        ['an invisible join phrase', [credit('Lead', ' \u200b '), { ...credit('Guest'), artistId: mbid(31) }], 'format'],
        ['an over-long join phrase', [credit('Lead', ' and together with '), { ...credit('Guest'), artistId: mbid(31) }], 'format']
    ] as const) {
        const result = flags(synthetic(1, { artistCredit: [...credits] }));
        assert.deepEqual(result.flagged, [{ path: 'album.artists', reason }], label);
        assert.equal(result.values.some(value => value.path === 'album.artists'), false, label);
    }
    const label = flags(synthetic(1, { labels: [{ name: 'l'.repeat(201), labelId: mbid(10), catalogNumber: null }] }));
    assert.deepEqual(label.flagged, [{ path: 'album.label', reason: 'length' }]);
    const longTrack = flags(synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [track(1, 't'.repeat(301)), track(2, 'Second\u200d')] }] }));
    assert.deepEqual(longTrack.flagged, [{ path: `tracks.${slot(0)}.title`, reason: 'length' }, { path: `tracks.${slot(1)}.title`, reason: 'characters' }]);
    assert.deepEqual(longTrack.values.filter(value => value.slotId).map(value => value.path), [`tracks.${slot(0)}.discNumber`, `tracks.${slot(0)}.trackNumber`,
        `tracks.${slot(1)}.discNumber`, `tracks.${slot(1)}.trackNumber`]);
    // Text is NFC and trimmed; a whitespace-only title is no value.
    assert.equal(flags(synthetic(1, { title: '  Cafe\u0301 ' })).values[0].value, 'Caf\u00e9');
    assert.equal(flags(synthetic(1, { title: '   ' })).values.some(value => value.path === 'album.title'), false);
});

test('the administrator\'s own values: equal case-insensitively is no conflict, a difference is an unanswered conflict that writes nothing, empty is filled, tag values are replaced', () => {
    const doc = project(2), draft = draftOf(doc);
    draft.album.title = 'Synthetic Album'; draft.album.artists = [{ ...entry('synthetic lead', 'primary', ' & '), key: mbid(800) }, { ...entry('Synthetic Second'), key: mbid(801) }];
    draft.album.label = { name: 'Mine', musicBrainzId: null }; draft.tracks[0].title = 'Tagged First';
    doc.draftOrigins = { 'album:title': 'administrator', 'album:artists': 'administrator', 'album:label': 'administrator', 'album:releaseDate': 'administrator',
        [`tracks:${slot(0)}:title`]: 'automatic' };
    const before = structuredClone(doc), { application, changed } = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    assert.equal(changed, true);
    assert.deepEqual(application.conflicts, [{ path: 'album.label', lookup: { name: 'Synthetic Label', musicBrainzId: mbid(10) }, slotId: null, answer: null }]);
    // Entries equal in names, roles and phrases keep the administrator's values and gain the candidate's MusicBrainz IDs.
    assert.deepEqual([draft.album.title, draft.album.artists, draft.album.label], [before.draft.album.title,
        (before.draft as ImportDraftV2).album.artists.map((item, index) => ({ ...item, musicBrainzId: mbid(index + 1) })), { name: 'Mine', musicBrainzId: null }]);
    assert.deepEqual([doc.draftOrigins['album:artists'], application.musicBrainzIds], ['administrator', [{ entryKey: mbid(800), musicBrainzId: mbid(1) }, { entryKey: mbid(801), musicBrainzId: mbid(2) }]]);
    assert.deepEqual([draft.album.releaseDate, doc.draftOrigins['album:releaseDate'], draft.tracks[0].title, doc.draftOrigins[`tracks:${slot(0)}:title`]],
        [{ year: 2020, month: 3, day: null }, 'automatic', 'First Song', 'automatic']);
    // Only automatic values equal to the candidate rest on it; the administrator's equal values stay theirs.
    assert.equal(application.values.some(value => ['album.title', 'album.artists', 'album.label'].includes(value.path)), false);
    assert.ok(application.values.some(value => value.path === 'album.releaseDate'));
    assert.deepEqual([doc.valueRevision, doc.revision, doc.receipts, doc.updatedAt], [1, 3, [], now]);
    assert.deepEqual(application.paths.sort(), ['album.artists', 'album.releaseDate', ...[0, 1].flatMap(index => ['title', 'discNumber', 'trackNumber'].map(field => `tracks.${slot(index)}.${field}`))].sort());
    // A label that differs only by case is the same label; another role or join phrase is a difference.
    assert.equal(sameLookupValue('album.label', { name: 'synthetic label', musicBrainzId: mbid(9) }, { name: 'Synthetic Label', musicBrainzId: null }), true);
    assert.equal(sameLookupValue('album.artists', [entry('Lead', 'featured')], [entry('lead')]), false);
    assert.equal(sameLookupValue('album.artists', [entry('Lead', 'primary', ' & ')], [entry('lead')]), false);
    assert.equal(sameLookupValue('album.label', null, null), true);
    assert.equal(sameLookupValue('album.label', null, { name: 'X', musicBrainzId: null }), false);
});

test('applying another candidate replaces only values still automatic; values the first wrote that the second lacks return to tag values or empty without an origin', () => {
    const doc = project(2, index => tags({ title: `Tagged ${index}`, album: 'Tagged Album', label: 'Tagged Label', albumArtists: ['Tagged Ensemble'] }));
    applyAutomaticValues({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, planImportAutomation(doc).values);
    const tagged = structuredClone(draftOf(doc));
    const first = applyLookupCandidate(doc, null, stored(synthetic(1)), intent({ choice: 'preselected', basis: 'onlyMatchingGroup', operationId: null }));
    assert.deepEqual([draftOf(doc).album.title, draftOf(doc).album.label, draftOf(doc).tracks.map(item => [item.title, item.discNumber, item.trackNumber])],
        ['Synthetic Album', { name: 'Synthetic Label', musicBrainzId: mbid(10) }, [['First Song', 1, 1], ['Second Song', 1, 2]]]);
    // The administrator then edits the second track's title.
    draftOf(doc).tracks[1].title = 'Typed Second'; doc.draftOrigins![`tracks:${slot(1)}:title`] = 'administrator';
    const second = synthetic(2, { title: 'Other Album', labels: [], groupFirstReleaseDate: null, date: null,
        media: [{ position: 1, format: 'CD', tracks: [track(1, 'A'), track(2, 'B'), track(3, 'C')] }] });
    const replaced = applyLookupCandidate(doc, first.application, stored(second), intent({ run: 2 }));
    const draft = draftOf(doc);
    assert.deepEqual([draft.album.title, draft.album.artists, draft.album.label, draft.album.releaseDate], ['Other Album', first.application.values[1].value, tagged.album.label, null]);
    assert.deepEqual(draft.tracks.map(item => [item.title, item.discNumber, item.trackNumber]), [['Tagged 0', null, null], ['Typed Second', null, null]]);
    // Emptied values have no origin; reverted tag values and the second candidate's values are automatic; the edit stays the administrator's.
    assert.deepEqual(Object.fromEntries(Object.entries(doc.draftOrigins!).sort()), Object.fromEntries(Object.entries({
        'album:artists': 'automatic', 'album:label': 'automatic', 'album:title': 'automatic', [`tracks:${slot(0)}:title`]: 'automatic', [`tracks:${slot(1)}:title`]: 'administrator'
    }).sort()));
    assert.deepEqual(replaced.application.values.map(value => value.path), ['album.title', 'album.artists']);
    assert.deepEqual([replaced.application.candidateKey, replaced.application.choice, replaced.changed, doc.valueRevision], [`musicbrainz:${mbid(2)}`, 'chosen', true, 2]);
});

test('choosing none returns lookup values to tag values, a previous answer to the same lookup value is kept, and the same candidate twice writes nothing', () => {
    const doc = project(2, index => tags({ title: `Tagged ${index}` }));
    applyAutomaticValues({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, planImportAutomation(doc).values);
    draftOf(doc).album.label = { name: 'Mine', musicBrainzId: null }; doc.draftOrigins!['album:label'] = 'administrator';
    const first = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    const answered: LookupApplication = { ...first.application, conflicts: first.application.conflicts.map(item => ({ ...item, answer: 'mine' as const })) };
    const snapshot = structuredClone(doc), again = applyLookupCandidate(doc, answered, stored(synthetic(1)), intent({ run: 2 }));
    assert.deepEqual([again.changed, doc.valueRevision, doc.draft, again.application.conflicts], [false, snapshot.valueRevision, snapshot.draft,
        [{ path: 'album.label', lookup: { name: 'Synthetic Label', musicBrainzId: mbid(10) }, slotId: null, answer: 'mine' }]]);
    // Another lookup value for the same path is a new question.
    const relabelled = applyLookupCandidate(copy(doc), answered, stored(synthetic(3, { labels: [{ name: 'Third Label', labelId: null, catalogNumber: null }] })), intent());
    assert.equal(relabelled.application.conflicts[0].answer, null);
    const none = applyLookupCandidate(doc, again.application, null, intent({ run: 2, choice: 'none', basis: null }));
    assert.deepEqual(draftOf(doc).tracks.map(item => [item.title, item.trackNumber]), [['Tagged 0', null], ['Tagged 1', null]]);
    assert.deepEqual([draftOf(doc).album.title, draftOf(doc).album.label, none.application.values, none.application.conflicts, none.application.candidateKey],
        ['', { name: 'Mine', musicBrainzId: null }, [], [], null]);
    assert.equal(doc.draftOrigins!['album:title'], undefined);
});

test('a track-count mismatch writes album values only, the 48 KB cap flags a value as size, and a path the stored draft lacks is skipped', () => {
    const three = synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [track(1, 'A'), track(2, 'B'), track(3, 'C')] }] });
    const doc = project(2), mismatch = applyLookupCandidate(doc, null, stored(three), intent());
    assert.deepEqual(mismatch.application.paths, ['album.title', 'album.artists', 'album.label', 'album.releaseDate']);
    const full = project(2), draft = draftOf(full);
    draft.album.title = 'x'.repeat(47_995 - JSON.stringify({ ...draft, album: { ...draft.album, title: '' } }).length); full.draftOrigins!['album:title'] = 'administrator';
    const capped = applyLookupCandidate(full, null, stored(synthetic(1)), intent());
    assert.ok(capped.application.flagged.some(flag => flag.path === `tracks.${slot(0)}.title` && flag.reason === 'size'));
    assert.equal(draft.tracks[0].title, '');
    assert.ok(JSON.stringify(full.draft).length <= 48_000);
    // A malformed stored draft that lost a track: that file's values and a recorded value on its path are skipped, the rest written.
    const lost = project(2); draftOf(lost).tracks.splice(1, 1);
    const previous: LookupApplication = { ...mismatch.application, values: [{ path: `tracks.${slot(1)}.title`, value: 'Gone', slotId: slot(1) }] };
    lost.draftOrigins![`tracks:${slot(1)}:title`] = 'automatic';
    const partial = applyLookupCandidate(lost, previous, stored(synthetic(1)), intent());
    assert.equal(partial.application.paths.some(item => item.includes(slot(1))), false);
    assert.ok(partial.application.paths.includes(`tracks.${slot(0)}.title`));
});

test('an entry keeps the key of the current entry with its folded name and others derive a stable key, so decisions on unchanged entries are kept', () => {
    const doc = project(2), kept = mbid(810);
    // The kept entry already carries the ID the candidate credits, and its decision binds it.
    draftOf(doc).album.artists = [{ key: kept, name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: mbid(1) }, { key: mbid(811), name: 'Gone', role: 'primary', joinPhrase: null, musicBrainzId: null }];
    doc.draftOrigins!['album:artists'] = 'automatic';
    const decision = (entryKey: string, boundName: string, boundMusicBrainzId: string | null = null) => ({ scope: 'artist', slotId: null, entryKey, boundName, boundMusicBrainzId, action: 'create-distinct', candidateId: null, candidateRevision: null });
    doc.decisions = [decision(kept, 'Synthetic Lead', mbid(1)), decision(mbid(811), 'Gone'), { ...decision(kept, 'x'), scope: 'album', entryKey: null, boundName: null }] as AdminImportDocument['decisions'];
    applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(doc).album.artists.map(item => item.key), [kept, derivedEntryKey({ importId, lookupEntry: 'synthetic second' })]);
    assert.deepEqual(doc.decisions.map(item => (item as { entryKey: string | null }).entryKey), [kept, null]);
    // The same entries on another import of the same ID derive the same keys.
    const fresh = project(2);
    applyLookupCandidate(fresh, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(fresh).album.artists, [entry('Synthetic Lead', 'primary', ' & ', mbid(1)), entry('Synthetic Second', 'primary', null, mbid(2))]);
});

test('a completed run applies its preselection once, never over this run\'s explicit choice, an unfetched candidate or a malformed draft', () => {
    const doc = project(2, timed), run = completed(doc, [stored(synthetic(1))]);
    assert.equal(run.ranking!.preselection?.basis, 'onlyMatchingGroup');
    const first = applyPreselectedLookup(doc, run, now);
    assert.deepEqual([first.changed, first.record.applied?.choice, first.record.applied?.basis, first.record.applied?.actorId, first.record.applied?.operationId, doc.valueRevision],
        [true, 'preselected', 'onlyMatchingGroup', actor, null, 1]);
    const again = applyPreselectedLookup(doc, first.record, now);
    assert.deepEqual([again.changed, again.record], [false, first.record]);
    const explicit = { ...run, applied: { ...first.record.applied!, choice: 'none' as const, candidateKey: null } };
    assert.equal(applyPreselectedLookup(project(2, timed), explicit, now).record, explicit);
    const unfetched = completed(doc, [stored(synthetic(1))]);
    unfetched.candidates = unfetched.candidates.map(candidate => ({ ...candidate, details: 'failed', release: null }));
    assert.equal(applyPreselectedLookup(project(2, timed), unfetched, now).changed, false);
    const malformed = project(2, timed, { draft: { album: null } as never });
    assert.deepEqual(applyPreselectedLookup(malformed, run, now), { record: run, changed: false });
    // An earlier run's application is replaced by this run's preselection.
    const earlier = applyPreselectedLookup(project(2, timed), { ...run, run: 2, applied: first.record.applied }, now);
    assert.equal(earlier.record.applied?.run, 2);
});

test('newly known durations re-rank stored candidates without a request and apply the new preselection; unchanged evidence re-ranks nothing', () => {
    const doc = project(2), run = completed(doc, [stored(synthetic(1)), stored(synthetic(2, { media: [{ position: 1, format: 'CD', tracks: [track(1, 'X', 100_000), track(2, 'Y', 100_000)] }] }))]);
    assert.equal(run.ranking!.preselection, null);
    assert.equal(rerankStoredLookup(doc, run, now), null);
    doc.media!.assets.forEach((asset, index) => { asset.tags = timed(index) as never; });
    const evidence = lookupFileEvidence(doc), reranked = rerankStoredLookup(doc, run, now, other)!;
    assert.deepEqual([reranked.changed, reranked.record.ranking!.preselection?.candidateKey, reranked.record.applied?.candidateKey, reranked.record.applied?.actorId,
        reranked.record.actorId, draftOf(doc).album.title], [true, `musicbrainz:${mbid(1)}`, `musicbrainz:${mbid(1)}`, other, actor, 'Synthetic Album']);
    assert.deepEqual(reranked.record.ranking!.files, evidence);
    // The Disc and Track Numbers the application wrote are no new evidence (they follow the ranking's file order).
    assert.notDeepEqual(lookupFileEvidence(doc), evidence);
    assert.equal(rerankStoredLookup(doc, reranked.record, now), null);
    for (const state of ['queued', 'stopped'] as const) assert.equal(rerankStoredLookup(doc, { ...run, state }, now), null, state);
    assert.equal(rerankStoredLookup(doc, { ...run, outcome: 'noRelease' }, now), null);
    assert.deepEqual(guard.attempts, []);
});

test('a re-rank binds the file set it ranked: a stale slot confirmed again is no longer stale, one still without a confirmed file stays stale', () => {
    const doc = project(3), bound = [0, 1, 2].map(index => ({ slotId: slot(index), operationId: mbid(400 + index), sha256: 'b'.repeat(64) }));
    const run = completed(doc, [stored(synthetic(1))], { files: bound, staleSlotIds: [slot(0), slot(2)] });
    // Slot 0's file was replaced and confirmed, slot 2's removed; durations are newly known.
    doc.media!.assets = doc.media!.assets.filter(asset => asset.slotId !== slot(2));
    doc.media!.assets.forEach((asset, index) => { asset.tags = timed(index) as never; });
    const reranked = rerankStoredLookup(doc, run, now)!;
    assert.deepEqual([reranked.record.staleSlotIds, reranked.record.files, reranked.record.fileSetDigest],
        [[slot(2)], [{ slotId: slot(0), operationId: mbid(500), sha256: 'a'.repeat(64) }, { slotId: slot(1), operationId: mbid(501), sha256: 'a'.repeat(64) },
            { slotId: slot(2), operationId: null, sha256: null }], run.fileSetDigest]);
});

test('publication waits for a tie until a choice for that run, and for unanswered conflicts whose value still differs; an append ignores Album conflicts', () => {
    const doc = project(2, timed), labelled = (id: number, name: string) => synthetic(id, { labels: [{ name, labelId: null, catalogNumber: null }] });
    const tie = completed(doc, [stored(labelled(1, 'First Label')), stored(labelled(2, 'Second Label'))]);
    assert.deepEqual([tie.ranking!.groups.length, tie.ranking!.preselection], [2, null]);
    assert.deepEqual(lookupAnswersNeeded(tie, doc, { append: false }), { tie: true, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded(tie, doc, { append: true }), { tie: true, conflicts: [] });
    const chosen = chooseLookupCandidate(doc, tie, { run: 1, candidateKey: `musicbrainz:${mbid(2)}`, actorId: other, operationId: mbid(701) }, now);
    assert.equal(lookupAnswersNeeded(chosen, doc, { append: false }).tie, false);
    assert.equal(lookupAnswersNeeded({ ...chosen, run: 2 }, doc, { append: false }).tie, true, 'a choice for an earlier run answers nothing now');
    const none = chooseLookupCandidate(project(2, timed), tie, { run: 1, candidateKey: null, actorId: other, operationId: mbid(702) }, now);
    assert.equal(lookupAnswersNeeded(none, doc, { append: false }).tie, false);
    assert.equal(lookupAnswersNeeded({ ...tie, state: 'stopped' }, doc, { append: false }).tie, false);

    const mine = project(2, timed);
    draftOf(mine).album.label = { name: 'Mine', musicBrainzId: null }; draftOf(mine).tracks[0].title = 'Mine'; mine.draftOrigins = { 'album:label': 'administrator', [`tracks:${slot(0)}:title`]: 'administrator' };
    const conflicted = applyPreselectedLookup(mine, completed(mine, [stored(synthetic(1))]), now).record;
    assert.deepEqual(lookupAnswersNeeded(conflicted, mine, { append: false }), { tie: false, conflicts: ['album.label', `tracks.${slot(0)}.title`] });
    assert.deepEqual(lookupAnswersNeeded(conflicted, mine, { append: true }).conflicts, [`tracks.${slot(0)}.title`]);
    // An answer, or a current value made equal (case-insensitively for a label), needs nothing more.
    const answered = { ...conflicted, applied: { ...conflicted.applied!, conflicts: conflicted.applied!.conflicts.map(item => ({ ...item, answer: 'mine' as const })) } };
    assert.deepEqual(lookupAnswersNeeded(answered, mine, { append: false }).conflicts, []);
    draftOf(mine).album.label = { name: 'SYNTHETIC LABEL', musicBrainzId: null };
    assert.deepEqual(lookupAnswersNeeded(conflicted, mine, { append: false }).conflicts, [`tracks.${slot(0)}.title`]);
    // Malformed stored items and records never block.
    const malformed = { ...conflicted, applied: { ...conflicted.applied!, conflicts: [null, { path: 'album.visibility', lookup: 'public', answer: null }, { path: 'album.title', lookup: 'x' },
        { path: '__proto__', lookup: 1, answer: null }] as never } };
    assert.deepEqual(lookupAnswersNeeded(malformed, mine, { append: false }), { tie: false, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded(null, mine, { append: false }), { tie: false, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded({ ...conflicted, ranking: 'x' as never, applied: 'y' as never }, mine, { append: false }), { tie: false, conflicts: [] });
});

test('one matching group of a partial comparison is offered, not applied, and needs no answer; choosing it applies it', () => {
    const doc = project(2, timed), partial = completed(doc, [stored(synthetic(1))], { searchComplete: false });
    assert.deepEqual([partial.ranking!.groups.length, partial.ranking!.preselection, partial.ranking!.disclosure.partialComparison], [1, null, true]);
    assert.deepEqual(applyPreselectedLookup(doc, partial, now), { record: partial, changed: false });
    assert.deepEqual([draftOf(doc).album.title, doc.valueRevision], ['', 0]);
    // One group is no tie: publication never waits for it.
    assert.deepEqual(lookupAnswersNeeded(partial, doc, { append: false }), { tie: false, conflicts: [] });
    assert.deepEqual(lookupAnswersNeeded(partial, doc, { append: true }), { tie: false, conflicts: [] });
    const chosen = chooseLookupCandidate(doc, partial, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, actorId: other, operationId: mbid(704) }, now);
    assert.deepEqual([lookupAnswersNeeded(chosen, doc, { append: false }).tie, chosen.applied?.choice, draftOf(doc).album.title], [false, 'chosen', 'Synthetic Album']);
    const none = chooseLookupCandidate(project(2, timed), partial, { run: 1, candidateKey: null, actorId: other, operationId: mbid(705) }, now);
    assert.equal(lookupAnswersNeeded(none, doc, { append: false }).tie, false);
    // Two matching groups of a partial comparison are still a tie.
    const two = completed(doc, [stored(synthetic(1)), stored({ ...synthetic(2), title: 'Synthetic Other' })], { searchComplete: false });
    assert.deepEqual([two.ranking!.groups.length, lookupAnswersNeeded(two, doc, { append: false }).tie], [2, true]);
    // A complete comparison preselects the same group, and without a matching candidate nothing is preselected and no choice is needed.
    assert.equal(completed(doc, [stored(synthetic(1))]).ranking!.preselection?.basis, 'onlyMatchingGroup');
    const nothing = completed(project(2), [stored(synthetic(1))], { searchComplete: false });
    assert.deepEqual([nothing.ranking!.groups, lookupAnswersNeeded(nothing, project(2), { append: false }).tie], [[], false]);
});

test('re-ranking a record without searchComplete never preselects its only group', () => {
    const doc = project(2), run = completed(doc, [stored(synthetic(1))]);
    const legacy = { ...run } as Partial<MetadataLookupRecord>;
    delete legacy.searchComplete;
    // Durations become known: a record from a release before the field is a partial comparison, so its only group is only offered.
    doc.media!.assets.forEach((asset, index) => { asset.tags = timed(index) as never; });
    const reranked = rerankStoredLookup(doc, legacy as MetadataLookupRecord, now)!;
    assert.deepEqual([reranked.changed, reranked.record.ranking!.groups.length, reranked.record.ranking!.preselection, reranked.record.ranking!.disclosure.partialComparison,
        reranked.record.applied, lookupAnswersNeeded(reranked.record, doc, { append: false }).tie], [false, 1, null, true, null, false]);
    // The same run with complete searches preselects and applies it.
    const complete = rerankStoredLookup(project(2, timed), { ...run, ranking: { ...run.ranking!, files: [] } }, now)!;
    assert.deepEqual([complete.changed, complete.record.ranking!.preselection?.basis], [true, 'onlyMatchingGroup']);
});

test('choosing refuses another run, an active run, a candidate before completion or unknown as stale, and one without fetched details as incomplete', () => {
    const doc = project(2, timed), run = completed(doc, [stored(synthetic(1)), stored(synthetic(2), 'failed')]);
    const choose = (record: MetadataLookupRecord | null, candidateKey: string | null, runNumber = 1) =>
        () => chooseLookupCandidate(project(2, timed), record, { run: runNumber, candidateKey, actorId: other, operationId: mbid(703) }, now);
    assert.throws(choose(null, null), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(choose(run, null, 2), code('ADMIN_IMPORT_LOOKUP_STALE'));
    for (const state of ['queued', 'running', 'retrying'] as const) assert.throws(choose({ ...run, state }, null), code('ADMIN_IMPORT_LOOKUP_STALE'), state);
    assert.throws(choose({ ...run, state: 'unavailable' }, `musicbrainz:${mbid(1)}`), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(choose(run, `musicbrainz:${mbid(9)}`), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(choose(run, `musicbrainz:${mbid(2)}`), code('ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE'));
    // A fetched release answered under another ID (a merged release) ranks as incomplete and is never chosen or preselected, so
    // its values never rest on evidence naming another release.
    const preselected = completed(doc, [stored(synthetic(1))]);
    const merged = { ...preselected, candidates: preselected.candidates.map(candidate => ({ ...candidate, release: synthetic(7, { title: 'Merged Target Album' }) })) };
    assert.throws(choose(merged, `musicbrainz:${mbid(1)}`), code('ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE'));
    assert.equal(completed(doc, merged.candidates).ranking!.candidates[0].status, 'incomplete');
    const target = project(2, timed);
    assert.deepEqual(applyPreselectedLookup(target, merged, now), { record: merged, changed: false });
    assert.deepEqual([draftOf(target).album.title, target.valueRevision], ['', 0]);
    // None is allowed in any finished state; a choice moves the grant to the chooser.
    for (const state of ['unavailable', 'stopped', 'superseded', 'complete'] as const) assert.equal(choose({ ...run, state }, null)().applied?.choice, 'none', state);
    const chosen = choose(run, `musicbrainz:${mbid(1)}`)();
    assert.deepEqual([chosen.applied?.choice, chosen.applied?.basis, chosen.applied?.actorId, chosen.applied?.operationId, chosen.actorId, chosen.grantSource,
        chosen.grantExpiresAt.getTime() - now.getTime()], ['chosen', 'chosen', other, mbid(703), other, 'choose', METADATA_LOOKUP_JOB_LIMITS.grantMs]);
});

test('answering a conflict: lookup writes the value as the administrator\'s own, mine keeps it, and a stale application, path or base is refused', () => {
    const setup = () => {
        const doc = project(2, timed);
        draftOf(doc).album.label = { name: 'Mine', musicBrainzId: null }; doc.draftOrigins = { 'album:label': 'administrator' };
        return { doc, record: applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record };
    };
    const key = `musicbrainz:${mbid(1)}`, base = { name: 'Mine', musicBrainzId: null };
    const resolve = (doc: AdminImportDocument, record: MetadataLookupRecord | null, answers: { path: string; answer: 'mine' | 'lookup'; base: unknown }[], run = 1, candidateKey: string | null = key) =>
        resolveLookupConflicts(doc, record, { run, candidateKey, answers: answers as never }, now);
    const { doc, record } = setup();
    const kept = resolve(copy(doc), record, [{ path: 'album.label', answer: 'mine', base }]);
    assert.equal(kept.applied!.conflicts[0].answer, 'mine');
    const taken = resolve(doc, record, [{ path: 'album.label', answer: 'lookup', base }]);
    // The lookup value's MusicBrainz ID came from the release, so answering lookup writes it too, and records it as supplied.
    assert.deepEqual([draftOf(doc).album.label, doc.draftOrigins!['album:label'], taken.applied!.conflicts[0].answer], [{ name: 'Synthetic Label', musicBrainzId: mbid(10) }, 'administrator', 'lookup']);
    assert.ok(taken.applied!.musicBrainzIds?.some(item => item.entryKey === null && item.musicBrainzId === mbid(10)));
    assert.deepEqual(doc.musicBrainzNames?.find(item => item.musicBrainzId === mbid(10))?.names, ['Synthetic Label']);
    assert.ok(taken.applied!.values.some(value => value.path === 'album.label'));
    assert.deepEqual(lookupAnswersNeeded(taken, doc, { append: false }).conflicts, []);
    for (const [label, run, candidateKey] of [['another run', 2, key], ['another candidate', 1, `musicbrainz:${mbid(2)}`], ['none', 1, null]] as const)
        assert.throws(() => resolve(setup().doc, record, [{ path: 'album.label', answer: 'mine', base }], run, candidateKey), code('ADMIN_IMPORT_LOOKUP_STALE'), label);
    assert.throws(() => resolve(setup().doc, { ...record, applied: null }, [{ path: 'album.label', answer: 'mine', base }]), code('ADMIN_IMPORT_LOOKUP_STALE'));
    assert.throws(() => resolve(setup().doc, record, [{ path: 'album.title', answer: 'mine', base: 'Synthetic Album' }]), code('ADMIN_IMPORT_LOOKUP_STALE'));
    const fresh = setup();
    assert.throws(() => resolve(fresh.doc, fresh.record, [{ path: 'album.label', answer: 'lookup', base: { name: 'Earlier', musicBrainzId: null } }]), code('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.deepEqual(draftOf(fresh.doc).album.label, base);
    const garbage = { ...fresh.record, applied: { ...fresh.record.applied!, conflicts: [{ path: 'album.label' as const, lookup: { name: '' }, slotId: null, answer: null }] } };
    assert.throws(() => resolve(fresh.doc, garbage, [{ path: 'album.label', answer: 'lookup', base }]), code('ADMIN_IMPORT_LOOKUP_STALE'));
});

test('Artist entries and a label equal to the applied lookup values do not rest on file tags alone; differing ones still do', () => {
    const doc = project(2, timed), record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record;
    const draft = draftOf(doc), values = record.applied!.values;
    assert.deepEqual(importAutomationMarkers(draft, doc.draftOrigins).tagOnly, { artists: true, label: true });
    const marked = importAutomationMarkers(draft, doc.draftOrigins, values);
    assert.deepEqual(marked.tagOnly, { artists: false, label: false });
    // Every automatic value here rests on the candidate: all stay automatic (an administrator save wins over them) and are listed
    // as lookup values, in draft path order, so neither the editor nor the confirmation calls them file-tag values.
    assert.deepEqual(marked.lookupPaths, marked.automaticPaths);
    assert.deepEqual(marked.automaticPaths, ['album.title', 'album.artists', 'album.label', 'album.releaseDate',
        ...[0, 1].flatMap(index => ['title', 'discNumber', 'trackNumber'].map(field => `tracks.${slot(index)}.${field}`))]);
    const relabelled = structuredClone(draft); relabelled.album.label = { name: 'Synthetic Records', musicBrainzId: null };
    relabelled.album.artists = [...relabelled.album.artists, { ...entry('Company Records'), role: 'primary' }];
    const automaticPaths = importAutomationMarkers(relabelled, doc.draftOrigins).automaticPaths;
    assert.deepEqual(importAutomationMarkers(relabelled, doc.draftOrigins, values), { automaticPaths,
        lookupPaths: automaticPaths.filter(path => path !== 'album.artists' && path !== 'album.label'), possibleLabelEntryKeys: [entry('Company Records').key], tagOnly: { artists: true, label: true } });
    // Malformed lookup values never count.
    const malformed = importAutomationMarkers(draft, doc.draftOrigins, [null, { path: 7 }, { path: 'album.label' }] as never);
    assert.deepEqual([malformed.tagOnly, malformed.lookupPaths], [{ artists: true, label: true }, []]);
});

test('file-tag automation never replaces a value still resting on the applied lookup candidate, and fills the values lookup did not write', () => {
    const doc = project(2, index => tags({ title: `Tagged ${index}`, album: 'Tagged Album', albumArtists: ['Tagged Ensemble'] }));
    const { application } = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    const paths = (lookupValues: LookupApplication['values'] = []) => planImportAutomation(doc, lookupValues).values.map(value => value.path);
    assert.deepEqual(paths(), [`tracks.${slot(0)}.title`, `tracks.${slot(1)}.title`, 'album.title', 'album.artists']);
    assert.deepEqual(paths(application.values), []);
    // A value no longer equal to the applied one (changed since) and a value the candidate never wrote are planned as before.
    draftOf(doc).album.title = 'Since Changed';
    const partial = { ...application, values: application.values.filter(value => value.path !== 'album.artists') };
    assert.deepEqual(paths(partial.values), ['album.title', 'album.artists']);
    // Run on a fresh copy, the plan writes only those, leaving the chosen candidate's track titles and entries as they are.
    const result = applyAutomaticValues({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, planImportAutomation(doc, application.values).values);
    assert.deepEqual([result.written, draftOf(doc).album.title, draftOf(doc).tracks.map(item => item.title)], [['album.title'], 'Tagged Album', ['First Song', 'Second Song']]);
});

test('answering lookup for the Artist entries keeps decisions on reused entries only, and an answer that grows the draft past its cap is invalid', () => {
    const doc = project(2, timed), kept = mbid(820), gone = mbid(821);
    // The kept entry already carries the ID the candidate credits (its decision binds it), so the answer changes neither.
    draftOf(doc).album.artists = [{ key: kept, name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: mbid(1) }, { key: gone, name: 'Mine', role: 'primary', joinPhrase: null, musicBrainzId: null }];
    doc.draftOrigins = { 'album:artists': 'administrator' };
    const decision = (entryKey: string, boundName: string, boundMusicBrainzId: string | null = null) => ({ scope: 'artist', slotId: null, entryKey, boundName, boundMusicBrainzId, action: 'create-distinct', candidateId: null, candidateRevision: null });
    doc.decisions = [decision(kept, 'Synthetic Lead', mbid(1)), decision(gone, 'Mine')] as AdminImportDocument['decisions'];
    const record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record;
    const conflict = record.applied!.conflicts.find(item => item.path === 'album.artists')!;
    assert.deepEqual((conflict.lookup as ImportArtistEntry[]).map(item => item.key), [kept, derivedEntryKey({ importId, lookupEntry: 'synthetic second' })]);
    const base = structuredClone(draftOf(doc).album.artists);
    const answered = resolveLookupConflicts(doc, record, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: 'album.artists', answer: 'lookup', base }] }, now);
    assert.deepEqual([draftOf(doc).album.artists.map(item => item.name), doc.draftOrigins!['album:artists'], doc.decisions.map(item => (item as { entryKey: string }).entryKey)],
        [['Synthetic Lead', 'Synthetic Second'], 'administrator', [kept]]);
    assert.deepEqual([answered.applied!.conflicts[0].answer, answered.applied!.values.find(item => item.path === 'album.artists')?.value], ['lookup', draftOf(doc).album.artists]);
    // Near the 48 KB cap, writing the longer lookup title is refused (the caller's transaction then writes nothing).
    const full = project(2, timed), slotPath = `tracks.${slot(0)}.title` as const;
    draftOf(full).tracks[0].title = 'x'; full.draftOrigins = { [`tracks:${slot(0)}:title`]: 'administrator' };
    const capped = applyPreselectedLookup(full, completed(full, [stored(synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [track(1, 't'.repeat(300)), track(2, 'Second Song')] }] }))]), now).record;
    assert.deepEqual(capped.applied!.conflicts.map(item => item.path), [slotPath]);
    const draft = draftOf(full);
    draft.album.title = 'x'.repeat(48_000 - 100 - JSON.stringify({ ...draft, album: { ...draft.album, title: '' } }).length);
    const keeping = copy(full);
    assert.throws(() => resolveLookupConflicts(full, capped, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: slotPath, answer: 'lookup', base: 'x' }] }, now),
        code('ADMIN_IMPORT_INVALID_INPUT'));
    // Keeping the current value never grows the draft.
    assert.equal(resolveLookupConflicts(keeping, capped, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: slotPath, answer: 'mine', base: 'x' }] }, now)
        .applied!.conflicts[0].answer, 'mine');
});

test('a conflict stored twice for one path is needed once', () => {
    const doc = project(2, timed);
    draftOf(doc).album.label = { name: 'Mine', musicBrainzId: null }; doc.draftOrigins = { 'album:label': 'administrator' };
    const record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now).record;
    const doubled = { ...record, applied: { ...record.applied!, conflicts: [...record.applied!.conflicts, ...record.applied!.conflicts] } };
    assert.deepEqual(lookupAnswersNeeded(doubled, doc, { append: false }), { tie: false, conflicts: ['album.label'] });
});

/** The administrator's own Artist entries and label equal to synthetic(1)'s, without IDs, and the given decisions. */
function ownEntries(decisions: Record<string, unknown>[] = []): AdminImportDocument {
    const doc = project(2, timed), draft = draftOf(doc);
    draft.album.artists = [{ ...entry('Synthetic Lead', 'primary', ' & '), key: mbid(830) }, { ...entry('Synthetic Second'), key: mbid(831) }];
    draft.album.label = { name: 'Synthetic Label', musicBrainzId: null };
    doc.draftOrigins = { 'album:artists': 'administrator', 'album:label': 'administrator' };
    doc.decisions = decisions as AdminImportDocument['decisions'];
    return doc;
}
const holderId = (n: number) => String(n).padStart(24, 'c');
const identity = (holders: [string, string][], storedIds: [string, string | null][] = []) => ({ identity: { holders: new Map(holders), storedIds: new Map(storedIds) }, aliases: new Map<string, string[]>(),
    localized: [] as string[][] });
const decided = (scope: 'artist' | 'label', entryKey: string | null, boundName: string, action: string, candidateId: string | null = null) =>
    ({ scope, slotId: null, entryKey, boundName, boundMusicBrainzId: null, action, candidateId, candidateRevision: candidateId ? 'a'.repeat(64) : null });

test('the administrator\'s own entries and label equal in names gain the candidate\'s MusicBrainz IDs without a decision; a different ID is a conflict', () => {
    const doc = ownEntries(), { application, changed } = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    assert.equal(changed, true);
    assert.deepEqual([draftOf(doc).album.artists.map(item => item.musicBrainzId), draftOf(doc).album.label], [[mbid(1), mbid(2)], { name: 'Synthetic Label', musicBrainzId: mbid(10) }]);
    // Additions keep the administrator's origin, count as automatic writes and are recorded as supplied by this candidate.
    assert.deepEqual([doc.draftOrigins!['album:artists'], doc.draftOrigins!['album:label'], doc.valueRevision, doc.revision], ['administrator', 'administrator', 1, 3]);
    assert.ok(application.paths.includes('album.artists') && application.paths.includes('album.label'));
    assert.deepEqual(application.musicBrainzIds, [{ entryKey: mbid(830), musicBrainzId: mbid(1) }, { entryKey: mbid(831), musicBrainzId: mbid(2) }, { entryKey: null, musicBrainzId: mbid(10) }]);
    assert.deepEqual(application.conflicts, []);
    // The names found for each carried ID are stored for renames and alias candidates.
    assert.deepEqual(doc.musicBrainzNames, [{ musicBrainzId: mbid(1), names: ['Synthetic Lead'] }, { musicBrainzId: mbid(2), names: ['Synthetic Second'] }, { musicBrainzId: mbid(10), names: ['Synthetic Label'] }]);
    // An entry already carrying another ID keeps it: the difference is a conflict marked as an ID conflict, and nothing is added there.
    const differing = ownEntries(); draftOf(differing).album.artists[0].musicBrainzId = mbid(77);
    const result = applyLookupCandidate(differing, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(differing).album.artists.map(item => item.musicBrainzId), [mbid(77), mbid(2)]);
    assert.deepEqual(result.application.conflicts, [{ path: 'album.artists', slotId: null, answer: null, musicBrainzId: true,
        lookup: draftOf(differing).album.artists.map((item, index) => ({ ...item, musicBrainzId: mbid(index + 1) })) }]);
    assert.deepEqual(lookupAnswersNeeded({ ...completed(differing, [stored(synthetic(1))]), applied: result.application }, differing, { append: false }).conflicts, ['album.artists']);
    // ID-aware equality: names equal and no position carrying two different IDs; a missing ID is no difference.
    const lead = { ...entry('Synthetic Lead'), musicBrainzId: mbid(1) };
    assert.equal(sameLookupValue('album.artists', [lead], [{ ...lead, musicBrainzId: null }]), true);
    assert.equal(sameLookupValue('album.artists', [lead], [{ ...lead, musicBrainzId: mbid(2) }]), false);
    assert.equal(sameLookupNames('album.artists', [lead], [{ ...lead, musicBrainzId: mbid(2) }]), true);
    assert.equal(sameLookupValue('album.label', { name: 'L', musicBrainzId: mbid(1) }, { name: 'l', musicBrainzId: mbid(2) }), false);
    assert.equal(sameLookupValue('album.title', 'A', 'A'), true);
});

test('an added ID keeps only a decision that stays valid and rebinds it to the ID; any other decision on that entry is cleared', () => {
    const lead = mbid(830), second = mbid(831);
    // Reusing the record that holds the ID, and reusing a record without an ID while no record holds it, stay valid.
    const valid = ownEntries([decided('artist', lead, 'Synthetic Lead', 'reuse', holderId(1)), decided('artist', second, 'Synthetic Second', 'reuse', holderId(2)),
        decided('label', null, 'Synthetic Label', 'create-distinct')]);
    applyLookupCandidate(valid, null, stored(synthetic(1)), intent(), identity([[`artist:${mbid(1)}`, holderId(1)]], [[`artist:${holderId(2)}`, null]]));
    assert.deepEqual(valid.decisions.map(item => [(item as { entryKey: string | null }).entryKey, (item as { boundMusicBrainzId?: string | null }).boundMusicBrainzId]),
        [[lead, mbid(1)], [second, mbid(2)], [null, mbid(10)]]);
    // Reusing a record holding another ID, reusing one while another record holds the ID, creating while a record holds it, a skip,
    // and a reuse of a record whose ID was not read are all cleared and shown again.
    const cleared = ownEntries([decided('artist', lead, 'Synthetic Lead', 'reuse', holderId(3)), decided('artist', second, 'Synthetic Second', 'reuse', holderId(4)),
        decided('label', null, 'Synthetic Label', 'create-distinct')]);
    applyLookupCandidate(cleared, null, stored(synthetic(1)), intent(), identity([[`artist:${mbid(2)}`, holderId(5)], [`organization:${mbid(10)}`, holderId(6)]], [[`artist:${holderId(3)}`, mbid(70)]]));
    assert.deepEqual(cleared.decisions, []);
    const others = ownEntries([decided('artist', lead, 'Synthetic Lead', 'skip'), decided('artist', second, 'Synthetic Second', 'reuse', holderId(7)), { scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }]);
    applyLookupCandidate(others, null, stored(synthetic(1)), intent());
    assert.deepEqual(others.decisions.map(item => item.scope), ['album']);
    // A decision stored without `boundMusicBrainzId` (by a release before IDs) binds none here too, as the draft rules read it: on
    // an entry that already carries an ID it is not bound, so the application's write drops it instead of binding it in place.
    const { boundMusicBrainzId: _bound, ...legacyDecision } = decided('artist', lead, 'Synthetic Lead', 'create-distinct');
    const legacy = ownEntries([legacyDecision]); draftOf(legacy).album.artists[0].musicBrainzId = mbid(1);
    assert.equal(applyLookupCandidate(legacy, null, stored(synthetic(1)), intent()).changed, true);
    assert.deepEqual(legacy.decisions, []);
});

test('choosing another candidate or none first removes the IDs the earlier one supplied, unless an explicit decision bound them; re-applying writes nothing', () => {
    const doc = ownEntries(), first = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    const snapshot = structuredClone(doc.draft), again = applyLookupCandidate(doc, first.application, stored(synthetic(1)), intent({ run: 2 }));
    assert.deepEqual([again.changed, doc.draft, doc.valueRevision], [false, snapshot, 1]);
    // The administrator decides the label, binding its ID; choosing none then removes only the entries' IDs, keeping origins.
    doc.decisions = [{ ...decided('label', null, 'Synthetic Label', 'create-distinct'), boundMusicBrainzId: mbid(10) }] as AdminImportDocument['decisions'];
    const none = applyLookupCandidate(doc, again.application, null, intent({ run: 2, choice: 'none', basis: null }));
    assert.deepEqual([draftOf(doc).album.artists.map(item => [item.name, item.musicBrainzId]), draftOf(doc).album.label],
        [[['Synthetic Lead', null], ['Synthetic Second', null]], { name: 'Synthetic Label', musicBrainzId: mbid(10) }]);
    assert.deepEqual([doc.draftOrigins!['album:artists'], none.application.paths.filter(path => path.startsWith('album.') && path !== 'album.title' && path !== 'album.releaseDate'),
        none.changed, doc.decisions.length], ['administrator', ['album.artists'], true, 1]);
    assert.deepEqual(doc.musicBrainzNames, [{ musicBrainzId: mbid(10), names: ['Synthetic Label'] }]);
    // Another candidate crediting other artists under the same names: the earlier IDs go first, so its IDs are added, not conflicts.
    const other = ownEntries(), applied = applyLookupCandidate(other, null, stored(synthetic(1)), intent());
    const moved = synthetic(2, { artistCredit: synthetic(1).artistCredit.map((credit, index) => ({ ...credit, artistId: mbid(60 + index) })) });
    const replaced = applyLookupCandidate(other, applied.application, stored(moved), intent({ run: 2 }));
    assert.deepEqual([draftOf(other).album.artists.map(item => item.musicBrainzId), replaced.application.conflicts], [[mbid(60), mbid(61)], []]);
    // A decision value application itself rebound to an added ID binds it for nobody: choosing none removes the ID, and the
    // decision stays bound to its entry, which carries no ID again. One the administrator saved after the supply keeps it.
    const reused = ownEntries([decided('artist', mbid(831), 'Synthetic Second', 'reuse', holderId(2))]);
    const supplied = applyLookupCandidate(reused, null, stored(synthetic(1)), intent(), identity([], [[`artist:${holderId(2)}`, null]]));
    assert.deepEqual(reused.decisions.map(item => [(item as { boundMusicBrainzId?: string | null }).boundMusicBrainzId, (item as { boundBy?: string }).boundBy]), [[mbid(2), 'lookup']]);
    const saved = copy(reused); saved.decisions = saved.decisions.map(item => { const { boundBy: _boundBy, ...rest } = item as Record<string, unknown>; return rest; }) as AdminImportDocument['decisions'];
    applyLookupCandidate(reused, supplied.application, null, intent({ run: 2, choice: 'none', basis: null }));
    assert.deepEqual([draftOf(reused).album.artists.map(item => item.musicBrainzId), reused.decisions.map(item => [(item as { boundMusicBrainzId?: string | null }).boundMusicBrainzId, 'boundBy' in (item as object)])],
        [[null, null], [[null, false]]]);
    applyLookupCandidate(saved, supplied.application, null, intent({ run: 2, choice: 'none', basis: null }));
    assert.deepEqual([draftOf(saved).album.artists.map(item => item.musicBrainzId), saved.decisions.map(item => (item as { boundMusicBrainzId?: string | null }).boundMusicBrainzId)], [[null, mbid(2)], [mbid(2)]]);
    // A candidate offering the same ID for an entry whose value differs from its own (it credits only the lead) does not keep it:
    // its value is a conflict, so every earlier ID goes, and only the label, equal to its own, keeps the ID it re-adds.
    const narrower = ownEntries(), wider = applyLookupCandidate(narrower, null, stored(synthetic(1)), intent());
    const leadOnly = synthetic(3, { artistCredit: [{ ...synthetic(1).artistCredit[0], joinPhrase: '' }] });
    const conflicting = applyLookupCandidate(narrower, wider.application, stored(leadOnly), intent({ run: 2 }));
    assert.deepEqual([draftOf(narrower).album.artists.map(item => item.musicBrainzId), draftOf(narrower).album.label?.musicBrainzId], [[null, null], mbid(10)]);
    assert.deepEqual([conflicting.application.conflicts.map(item => [item.path, item.musicBrainzId ?? false]), conflicting.application.musicBrainzIds], [[['album.artists', false]], [{ entryKey: null, musicBrainzId: mbid(10) }]]);
    // An automatic value the earlier candidate wrote loses its IDs with the value it is replaced by.
    const automatic = project(2, timed), wrote = applyLookupCandidate(automatic, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(automatic).album.artists.map(item => item.musicBrainzId), [mbid(1), mbid(2)]);
    applyLookupCandidate(automatic, wrote.application, null, intent({ choice: 'none', basis: null }));
    assert.deepEqual(draftOf(automatic).album.artists, []);
});

test('an ID another entry already carries is never added to a second entry; the differing first entry is an ID conflict', () => {
    const doc = ownEntries(); draftOf(doc).album.artists[0].musicBrainzId = mbid(2);
    const { application } = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
    assert.deepEqual(draftOf(doc).album.artists.map(item => item.musicBrainzId), [mbid(2), null]);
    assert.deepEqual(application.conflicts.map(item => [item.path, item.musicBrainzId, (item.lookup as ImportArtistEntry[]).map(value => value.musicBrainzId)]), [['album.artists', true, [mbid(1), mbid(2)]]]);
    assert.deepEqual(application.musicBrainzIds, [{ entryKey: null, musicBrainzId: mbid(10) }]);
});

test('an administrator save wins over IDs lookup added or removed meanwhile: a base without them is current, the save keeps them, and a real difference still conflicts', () => {
    /** The administrator's own entries and label as the editor read them, then the candidate's IDs added by lookup. */
    const supplied = () => {
        const doc = ownEntries(), base = structuredClone(draftOf(doc).album.artists), label = structuredClone(draftOf(doc).album.label);
        const applied = applyLookupCandidate(doc, null, stored(synthetic(1)), intent());
        return { doc, base, label, applied, save: (changes: unknown[]) => applyAdministratorChanges({ draft: draftOf(doc), draftOrigins: doc.draftOrigins! }, parseDraftChanges(changes, doc.manifest, draftOf(doc))) };
    };
    // The editor still holds the entries and label as typed, without IDs: a role change and a case-only rename are admitted.
    const { doc, base, label, save } = supplied();
    assert.deepEqual(draftOf(doc).album.artists.map(item => item.musicBrainzId), [mbid(1), mbid(2)]);
    assert.deepEqual(save([{ path: 'album.artists', base, value: [base[0], { ...base[1], role: 'featured' }] }, { path: 'album.label', base: label, value: { name: 'synthetic label', musicBrainzId: null } }]),
        ['album.artists', 'album.label']);
    assert.deepEqual([draftOf(doc).album.artists.map(item => [item.role, item.musicBrainzId]), draftOf(doc).album.label], [[['primary', mbid(1)], ['featured', mbid(2)]], { name: 'synthetic label', musicBrainzId: mbid(10) }]);
    // A rename the ID was not found under leaves that entry without it; the other keeps its own.
    const rename = supplied();
    rename.save([{ path: 'album.artists', base: rename.base, value: [rename.base[0], { ...rename.base[1], name: 'Renamed Second' }] }]);
    assert.deepEqual(draftOf(rename.doc).album.artists.map(item => [item.name, item.musicBrainzId]), [['Synthetic Lead', mbid(1)], ['Renamed Second', null]]);
    // Another administrator's change to names, roles or phrases is still a conflict, writing nothing.
    const changed = supplied(); draftOf(changed.doc).album.artists[1].role = 'featured';
    const snapshot = structuredClone(changed.doc.draft);
    assert.throws(() => changed.save([{ path: 'album.artists', base: changed.base, value: [{ ...changed.base[0], joinPhrase: ' + ' }, changed.base[1]] }]), code('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.deepEqual(changed.doc.draft, snapshot);
    // The merge never makes malformed input valid: a value that is no entry list or label, or a malformed base, is judged as sent.
    const malformed = supplied();
    for (const [path, base, value] of [['album.artists', malformed.base, 'not entries'], ['album.artists', [null, 7], [{ ...malformed.base[0], musicBrainzId: mbid(77) }, malformed.base[1]]],
        ['album.label', 'not a label', { name: 'Synthetic Label', musicBrainzId: mbid(77) }], ['album.label', malformed.label, ['not a label']]] as const) {
        assert.throws(() => malformed.save([{ path, base, value }]), code('ADMIN_IMPORT_INVALID_INPUT'), JSON.stringify(value));
    }
    // The reverse: the editor read the IDs, then choosing none removed them; the save neither re-adds them nor is refused.
    const removed = supplied(), withIds = structuredClone(draftOf(removed.doc).album.artists);
    applyLookupCandidate(removed.doc, removed.applied.application, null, intent({ run: 2, choice: 'none', basis: null }));
    removed.save([{ path: 'album.artists', base: withIds, value: [withIds[0], { ...withIds[1], role: 'featured' }] }]);
    assert.deepEqual(draftOf(removed.doc).album.artists.map(item => [item.role, item.musicBrainzId]), [['primary', null], ['featured', null]]);
    // An ID the sender cleared stays cleared, while the one it left takes the ID another candidate put in its place.
    const cleared = supplied(), shown = structuredClone(draftOf(cleared.doc).album.artists);
    const moved = synthetic(2, { artistCredit: synthetic(1).artistCredit.map((credit, index) => ({ ...credit, artistId: mbid(60 + index) })) });
    applyLookupCandidate(cleared.doc, cleared.applied.application, stored(moved), intent({ run: 2 }));
    cleared.save([{ path: 'album.artists', base: shown, value: [{ ...shown[0], musicBrainzId: null }, shown[1]] }]);
    assert.deepEqual(draftOf(cleared.doc).album.artists.map(item => item.musicBrainzId), [null, mbid(61)]);
});

test('answering lookup on an ID conflict writes the release\'s IDs; the run\'s aliases join the names found for each ID', () => {
    const doc = ownEntries(); draftOf(doc).album.label = { name: 'Synthetic Label', musicBrainzId: mbid(77) };
    const context = { ...identity([]), aliases: new Map([[mbid(1), ['リード', 'Synthetic Lead']], [mbid(10), ['シンセ・レーベル']]]) };
    const record = applyPreselectedLookup(doc, completed(doc, [stored(synthetic(1))]), now, actor, context).record;
    assert.deepEqual(record.applied!.conflicts.map(item => [item.path, item.musicBrainzId]), [['album.label', true]]);
    assert.deepEqual(doc.musicBrainzNames?.find(item => item.musicBrainzId === mbid(1))?.names, ['Synthetic Lead', 'リード']);
    const answered = resolveLookupConflicts(doc, record, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, answers: [{ path: 'album.label', answer: 'lookup', base: draftOf(doc).album.label }] }, now);
    assert.deepEqual(draftOf(doc).album.label, { name: 'Synthetic Label', musicBrainzId: mbid(10) });
    assert.ok(answered.applied!.musicBrainzIds!.some(item => item.entryKey === null && item.musicBrainzId === mbid(10)));
    assert.deepEqual(lookupAnswersNeeded(answered, doc, { append: false }).conflicts, []);
});

test('track credits never change the values an import application writes, the candidate IDs it reads or the names it finds', () => {
    const guest = { name: 'Synthetic Guest', joinPhrase: ' feat. ', artistId: mbid(3), artistName: 'Synthetic Guest' };
    const plain = synthetic(1);
    const credited = synthetic(1, { media: [{ position: 1, format: 'CD', tracks: [{ ...track(1, 'First Song'), artistCredit: 'release' as const },
        { ...track(2, 'Second Song'), artistCredit: [guest, { name: 'Track Lead Spelling', joinPhrase: '', artistId: mbid(1), artistName: 'Track Lead Spelling' }] }] }] });
    assert.deepEqual(valuesOf(project(2, timed), credited), valuesOf(project(2, timed), plain));
    assert.deepEqual(lookupCandidateIds({ candidates: [stored(credited)] }), lookupCandidateIds({ candidates: [stored(plain)] }));
    // Applying the preselection writes the same draft, origins and found names: a track's other spelling of the lead adds no name.
    const applied = (release: MusicBrainzRelease) => {
        const doc = project(2, timed), result = applyPreselectedLookup(doc, completed(doc, [stored(release)]), now);
        return { changed: result.changed, values: result.record.applied!.values, draft: doc.draft, origins: doc.draftOrigins, names: doc.musicBrainzNames };
    };
    assert.deepEqual(applied(credited), applied(plain));
    assert.ok(!/Synthetic Guest|Track Lead Spelling/.test(JSON.stringify(applied(credited))));
});

test('the identity state an application needs is every fetched candidate\'s credited IDs and the records explicit decisions reuse', () => {
    const run = completed(project(2, timed), [stored(synthetic(1)), stored(synthetic(2), 'failed')]);
    assert.deepEqual(lookupCandidateIds(run), [{ kind: 'artist', id: mbid(1) }, { kind: 'artist', id: mbid(2) }, { kind: 'organization', id: mbid(10) }]);
    const doc = ownEntries([decided('artist', mbid(830), 'Synthetic Lead', 'reuse', holderId(1)), decided('label', null, 'Synthetic Label', 'replace', holderId(2)),
        decided('artist', mbid(831), 'Synthetic Second', 'create-distinct'), { scope: 'track', action: 'reuse', candidateId: holderId(3) }]);
    assert.deepEqual(lookupDecisionRecords(doc), [{ kind: 'artist', id: holderId(1) }, { kind: 'organization', id: holderId(2) }]);
});

test('a release with front artwork queues its cover staging under the intent\'s actor and grant, as a change that never bumps valueRevision', () => {
    const doc = project(2, timed), grant = new Date(now.getTime() + 5_000), later = new Date(now.getTime() + 1_000);
    // A release without front artwork writes its values and queues nothing.
    const first = applyLookupCandidate(doc, null, stored(synthetic(1)), intent({ grantExpiresAt: grant }));
    assert.deepEqual([first.changed, doc.valueRevision, doc.media!.lookupCover], [true, 1, undefined]);
    // Another release with the same values but front artwork changes only the cover job.
    const second = applyLookupCandidate(doc, first.application, stored(synthetic(3, { frontArtwork: true })), intent({ actorId: other, grantExpiresAt: grant, now: later }));
    assert.deepEqual([second.changed, second.application.paths, doc.valueRevision, doc.updatedAt], [true, [], 1, now]);
    assert.deepEqual([doc.media!.lookupCover!.candidateKey, doc.media!.lookupCover!.releaseId, doc.media!.lookupCover!.state, doc.media!.lookupCover!.actorId,
        doc.media!.lookupCover!.grantExpiresAt, doc.media!.lookupCover!.due, doc.media!.lookupCover!.updatedAt], [`musicbrainz:${mbid(3)}`, mbid(3), 'queued', other, grant, true, later]);
    // The same candidate again writes nothing; one without artwork leaves the job idle for the pass to clean.
    const queued = structuredClone(doc.media!.lookupCover);
    assert.equal(applyLookupCandidate(doc, second.application, stored(synthetic(3, { frontArtwork: true })), intent({ now: later })).changed, false);
    assert.deepEqual(doc.media!.lookupCover, queued);
    const third = applyLookupCandidate(doc, second.application, stored(synthetic(1)), intent({ now: later }));
    assert.deepEqual([third.changed, doc.valueRevision, doc.media!.lookupCover!.state, doc.media!.lookupCover!.candidateKey], [true, 1, 'idle', null]);
    // Without a grant in the intent, a fresh lookup grant from the application's time bounds the staging.
    const fresh = project(2, timed);
    applyLookupCandidate(fresh, null, stored(synthetic(4, { frontArtwork: true })), intent());
    assert.deepEqual(fresh.media!.lookupCover!.grantExpiresAt, new Date(now.getTime() + METADATA_LOOKUP_JOB_LIMITS.grantMs));
    // Choosing none without an earlier artwork candidate records no job.
    const none = project(2, timed);
    applyLookupCandidate(none, null, null, intent({ choice: 'none', basis: null }));
    assert.equal(none.media!.lookupCover, undefined);
});

test('the worker\'s preselection stages under the run\'s grant, while a re-rank and a choice stage under a fresh grant of the administrator acting', () => {
    const doc = project(2, timed), run = completed(doc, [stored(synthetic(1, { frontArtwork: true }))]);
    applyPreselectedLookup(doc, run, now);
    assert.deepEqual([doc.media!.lookupCover!.state, doc.media!.lookupCover!.actorId, doc.media!.lookupCover!.grantExpiresAt], ['queued', actor, run.grantExpiresAt]);
    // A run whose grant is unreadable falls back to a fresh one.
    const unreadable = project(2, timed);
    applyPreselectedLookup(unreadable, { ...completed(unreadable, [stored(synthetic(1, { frontArtwork: true }))]), grantExpiresAt: 'x' as unknown as Date }, now);
    assert.deepEqual(unreadable.media!.lookupCover!.grantExpiresAt, new Date(now.getTime() + METADATA_LOOKUP_JOB_LIMITS.grantMs));
    // A re-rank applies its new preselection as the confirming administrator with a fresh grant.
    const ranked = project(2), stale = completed(ranked, [stored(synthetic(1, { frontArtwork: true })),
        stored(synthetic(2, { media: [{ position: 1, format: 'CD', tracks: [track(1, 'X', 100_000), track(2, 'Y', 100_000)] }] }))]);
    ranked.media!.assets.forEach((asset, index) => { asset.tags = timed(index) as never; });
    const later = new Date(now.getTime() + 30_000);
    assert.equal(rerankStoredLookup(ranked, stale, later, other)!.changed, true);
    assert.deepEqual([ranked.media!.lookupCover!.actorId, ranked.media!.lookupCover!.grantExpiresAt], [other, new Date(later.getTime() + METADATA_LOOKUP_JOB_LIMITS.grantMs)]);
    // A choice moves the run's grant to the chooser, and the staging uses the same grant.
    const chosen = project(2, timed), record = chooseLookupCandidate(chosen, completed(chosen, [stored(synthetic(1, { frontArtwork: true }))]),
        { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, actorId: other, operationId: mbid(701) }, later);
    assert.deepEqual([chosen.media!.lookupCover!.actorId, chosen.media!.lookupCover!.grantExpiresAt, chosen.media!.lookupCover!.state], [other, record.grantExpiresAt, 'queued']);
    chooseLookupCandidate(chosen, record, { run: 1, candidateKey: null, actorId: other, operationId: mbid(702) }, later);
    assert.deepEqual([chosen.media!.lookupCover!.state, chosen.media!.lookupCover!.candidateKey], ['idle', null]);
});

test('an application that is refused queues no cover staging', () => {
    const doc = project(2, timed), run = completed(doc, [stored(synthetic(1, { frontArtwork: true }), 'failed')]);
    assert.throws(() => chooseLookupCandidate(doc, run, { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, actorId: other, operationId: mbid(701) }, now), code('ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE'));
    assert.equal(doc.media!.lookupCover, undefined);
    // A malformed stored draft refuses the whole application, before the cover job is recorded.
    const malformed = project(2, timed); (malformed as unknown as { draft: unknown }).draft = { album: 42 };
    assert.throws(() => applyLookupCandidate(malformed, null, stored(synthetic(1, { frontArtwork: true })), intent()));
    assert.equal(malformed.media!.lookupCover, undefined);
    assert.equal(applyPreselectedLookup(malformed, completed(project(2, timed), [stored(synthetic(1, { frontArtwork: true }))]), now).changed, false);
    assert.equal(malformed.media!.lookupCover, undefined);
});

const mzstatic = 'https://is1-ssl.mzstatic.com/image/thumb/Music126/v4/53/0f/80/530f802b/ANTCD-46555.jpg/100x100bb.jpg';
/** An iTunes-only candidate of collection `id` with two songs matching the timed files (milliseconds), as the iTunes stage stores it. */
const itunesStored = (id: string, check: 'noRelease' | 'unavailable' | 'notRun', artworkUrl: string | null = mzstatic, artist = 'Synthetic Ensemble feat. Synthetic Guest'): StoredLookupCandidate => {
    const collection = { collectionId: id, collectionName: 'Synthetic Album - Single', artistName: artist, trackCount: 2, releaseDate: { year: 2022, month: 8, day: 17 }, country: 'JPN', artworkUrl };
    const songs = [[2, 'Second Song', 220_010], [1, 'First Song', 209_990]].map(([trackNumber, trackName, trackTimeMillis]) => ({ trackId: `${id}${trackNumber}`, collectionId: id,
        collectionName: 'Box Set Disc', trackName: trackName as string, artistName: artist, discNumber: 1, discCount: 1, trackNumber: trackNumber as number, trackTimeMillis: trackTimeMillis as number }));
    return { ...itunesCandidate({ key: `collection:${id}`, kind: 'collection', collectionId: id, names: [{ storefront: 'jp', title: collection.collectionName, artist }], barcode: null,
        bridge: check, collection: 'pending' }, { collections: [collection], tracks: songs })! };
};
/** A run whose iTunes stage showed `artist` under another storefront's name. */
const localizedStage = (names: [string, string][]): MetadataLookupRecord['itunesStage'] => ({ reason: 'noMatch', text: 'synthetic album', requests: [], requestIndex: 0, bridge: [], bridgeIndex: 0,
    bridgeOutcomes: [], state: 'answered', complete: true, finalized: true, items: names.map(([us, jp], index) => ({ key: `collection:${900 + index}`, kind: 'collection', collectionId: String(900 + index),
        names: [{ storefront: 'us', title: 'X', artist: us }, { storefront: 'jp', title: 'X', artist: jp }], barcode: null, bridge: 'noRelease', collection: 'fetched' })) });

test('an iTunes-only candidate applies its collection name as given, its artist string as one entry, no label, its iTunes date and its tracks by milliseconds, with the collection ID as evidence', () => {
    const doc = project(2, timed), candidate = itunesStored('1613862586', 'unavailable');
    const { application, changed } = applyLookupCandidate(doc, null, candidate, intent({ choice: 'preselected', basis: 'onlyMatchingGroup' }));
    const draft = draftOf(doc);
    assert.deepEqual([changed, draft.album.title, draft.album.artists.map(item => [item.name, item.role, item.joinPhrase, item.musicBrainzId]), draft.album.label, draft.album.releaseDate],
        [true, 'Synthetic Album - Single', [['Synthetic Ensemble feat. Synthetic Guest', 'primary', null, null]], null, { year: 2022, month: 8, day: 17 }]);
    assert.deepEqual(draft.tracks.map(item => [item.title, item.discNumber, item.trackNumber]), [['First Song', 1, 1], ['Second Song', 1, 2]]);
    assert.deepEqual([application.candidateKey, application.releaseId, application.source, application.notChecked, application.paths.includes('album.label'), application.musicBrainzIds],
        ['itunes:1613862586', '1613862586', 'itunes', true, false, undefined]);
    // Not checked only when MusicBrainz was unavailable or the bridge did not run; a MusicBrainz candidate records neither.
    assert.equal(applyLookupCandidate(project(2, timed), null, itunesStored('1', 'noRelease'), intent()).application.notChecked, undefined);
    assert.equal(applyLookupCandidate(project(2, timed), null, itunesStored('1', 'notRun'), intent()).application.notChecked, true);
    const musicBrainz = applyLookupCandidate(project(2, timed), null, stored(synthetic(1)), intent()).application;
    assert.deepEqual([musicBrainz.source, musicBrainz.notChecked], [undefined, undefined]);
    // A choice applies an iTunes-only candidate whose details agree with its key; another collection ID in its release is incomplete.
    const run = completed(project(2, timed), [candidate]);
    assert.equal(chooseLookupCandidate(project(2, timed), run, { run: 1, candidateKey: candidate.key, actorId: actor, operationId: mbid(701) }, now).applied!.source, 'itunes');
    const broken = completed(project(2, timed), [{ ...candidate, release: { ...candidate.release!, releaseId: '1613862587' } }]);
    assert.throws(() => chooseLookupCandidate(project(2, timed), broken, { run: 1, candidateKey: candidate.key, actorId: actor, operationId: mbid(702) }, now), code('ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE'));
});

test('the run\'s localized name groups that hold a current Artist entry\'s name join the import, and stay after choosing none while the entry keeps that name', () => {
    const doc = project(2, timed), candidate = itunesStored('7', 'noRelease', null, 'Isekaijoucho');
    const context = { identity: { holders: new Map(), storedIds: new Map() }, aliases: new Map(), localized: [['Isekaijoucho', 'ヰ世界情緒'], ['Unrelated', 'Other']] };
    const first = applyLookupCandidate(doc, null, candidate, intent(), context);
    assert.deepEqual([first.changed, doc.localizedNames], [true, [['Isekaijoucho', 'ヰ世界情緒']]]);
    // The same application again changes nothing; choosing none reverts the values, and the group no longer holds an entry's name.
    assert.equal(applyLookupCandidate(doc, first.application, candidate, intent(), context).changed, false);
    applyLookupCandidate(doc, first.application, null, intent({ choice: 'none', basis: null }), context);
    assert.deepEqual([draftOf(doc).album.artists, doc.localizedNames], [[], []]);
    // An administrator's own entry with that name keeps its group through none.
    const own = project(2, timed);
    draftOf(own).album.artists = [entry('ヰ世界情緒')]; own.draftOrigins = { 'album:artists': 'administrator' };
    applyLookupCandidate(own, null, null, intent({ choice: 'none', basis: null }), context);
    assert.deepEqual(own.localizedNames, [['Isekaijoucho', 'ヰ世界情緒']]);
    // Answering conflicts merges the run's groups the same way.
    const answered = project(2, timed);
    draftOf(answered).album.title = 'Mine'; answered.draftOrigins = { 'album:title': 'administrator' };
    const record = applyPreselectedLookup(answered, completed(answered, [candidate], { itunesStage: localizedStage([['Isekaijoucho', 'ヰ世界情緒']]) }), now).record;
    answered.localizedNames = undefined;
    resolveLookupConflicts(answered, record, { run: 1, candidateKey: candidate.key, answers: [{ path: 'album.title', answer: 'mine', base: 'Mine' }] }, now);
    assert.deepEqual(answered.localizedNames, [['Isekaijoucho', 'ヰ世界情緒']]);
});

test('a completed run that applies nothing still keeps its localized name groups for the current Artist entries; a run still active, an unchanged one or a malformed draft writes none', () => {
    const doc = project(2, timed), context = { identity: { holders: new Map(), storedIds: new Map() }, aliases: new Map(), localized: [['Isekaijoucho', 'ヰ世界情緒'], ['Unrelated', 'Other']] };
    draftOf(doc).album.artists = [entry('Isekaijoucho')];
    // A lone iTunes-only result that does not match (three tracks for two files) leaves nothing preselected.
    const unmatched = itunesStored('7', 'noRelease', null, 'Isekaijoucho');
    const run = completed(doc, [{ ...unmatched, release: { ...unmatched.release!, media: [{ ...unmatched.release!.media[0], tracks: [track(1, 'A'), track(2, 'B'), track(3, 'C')] }] } }]);
    assert.equal(run.ranking!.preselection, null);
    const first = applyPreselectedLookup(doc, run, now, actor, context);
    assert.deepEqual([first.changed, first.record, doc.localizedNames, doc.valueRevision, draftOf(doc).album.title], [true, run, [['Isekaijoucho', 'ヰ世界情緒']], 0, '']);
    // Nothing new: unchanged, as it is for a run that is not complete or a draft that cannot be read.
    assert.equal(applyPreselectedLookup(doc, run, now, actor, context).changed, false);
    const active = project(2, timed);
    draftOf(active).album.artists = [entry('Isekaijoucho')];
    assert.deepEqual([applyPreselectedLookup(active, { ...run, state: 'running' }, now, actor, context).changed, active.localizedNames], [false, undefined]);
    const malformed = project(2, timed, { draft: { album: null } as never });
    assert.deepEqual([applyPreselectedLookup(malformed, run, now, actor, context).changed, malformed.localizedNames], [false, undefined]);
    // A re-rank that leaves nothing preselected keeps them the same way.
    const reranked = project(2, timed);
    draftOf(reranked).album.artists = [entry('ヰ世界情緒')];
    const result = rerankStoredLookup(reranked, { ...run, ranking: { ...run.ranking!, files: [] } }, now, actor, context);
    assert.deepEqual([result?.changed, result?.record.ranking?.preselection, reranked.localizedNames], [true, null, [['Isekaijoucho', 'ヰ世界情緒']]]);
});

test('an iTunes-only candidate queues its iTunes artwork with the stored address; a MusicBrainz candidate the bridge found never gets iTunes artwork or an iTunes date', () => {
    const doc = project(2, timed);
    applyLookupCandidate(doc, null, itunesStored('1689358563', 'noRelease'), intent());
    assert.deepEqual([doc.media!.lookupCover!.candidateKey, doc.media!.lookupCover!.releaseId, doc.media!.lookupCover!.artworkUrl, doc.media!.lookupCover!.state],
        ['itunes:1689358563', '1689358563', mzstatic, 'queued']);
    // Without an artwork address on the fixed hosts there is no artwork to stage.
    const bare = project(2, timed);
    applyLookupCandidate(bare, null, itunesStored('1689358563', 'noRelease', null), intent());
    assert.equal(bare.media!.lookupCover, undefined);
    // A bridged MusicBrainz release keeps its group's first-release date and Cover Art Archive artwork, whatever iTunes showed.
    const bridged = project(2, timed);
    applyLookupCandidate(bridged, null, { ...stored(synthetic(1, { frontArtwork: true })), basis: 'songText' }, intent());
    assert.deepEqual([draftOf(bridged).album.releaseDate, bridged.media!.lookupCover!.candidateKey, bridged.media!.lookupCover!.artworkUrl],
        [{ year: 2020, month: 3, day: null }, `musicbrainz:${mbid(1)}`, undefined]);
    // A MusicBrainz candidate stored with an iTunes address it should not have offers only Cover Art Archive artwork.
    const forged = project(2, timed);
    applyLookupCandidate(forged, null, { ...stored(synthetic(2, { frontArtwork: true })), itunes: { storefront: 'jp', artworkUrl: mzstatic, check: 'noRelease' } }, intent());
    assert.equal(forged.media!.lookupCover!.artworkUrl, undefined);
});
